sudo install -d -o syslog -g adm -m 0755 /var/log/inventory; sudo tee /etc/rsyslog.d/10-inventory-collector.conf >/dev/null <<'ANTRIEB_RSYSLOG'
module(load="imtcp")

template(name="InventoryNode2Format" type="string" string="%timereported:::date-rfc3339% %hostname% %syslogtag%%msg%\n")

ruleset(name="inventoryFromNode2") {
    if ($fromhost-ip == '10.100.59.11' and $programname == 'inventory') then {
        action(type="omfile" file="/var/log/inventory/node2.log" template="InventoryNode2Format" fileOwner="syslog" fileGroup="adm" fileCreateMode="0640" dirCreateMode="0755")
        stop
    }
}

input(type="imtcp" port="514" ruleset="inventoryFromNode2")
ANTRIEB_RSYSLOG
sudo rsyslogd -N1

